-- ----------------------------------------------------------------------------
-- 1. COPIA DE LA BASE ORIGINAL
-- ----------------------------------------------------------------------------
DROP database IF EXISTS ambiental_raw;
create database if not exists ambiental_raw CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci; -- CHARACTERSETutf8mb4 define los caracteres que MySQL puede almacenar, incluyendo tildes, ñ, símbolos y emojis. Qué tipo de caracteres puedo manejar?
use ambiental_raw;                                                                            -- COLLATE utf8mb4_0900_ai_ci define las reglas para comparar y ordenar esos textos, siendo ci no sensible a mayúsculas y ai no sensible a tildes.

-- CREACIÓN TABLA MUNICIPIOS

CREATE TABLE if not exists `raw_municipios` (
  `municipio_id` varchar(10) NOT NULL,
  `municipio` varchar(100) DEFAULT NULL,     -- DEFAULT NULL si no se proporciona un valor para esa columna al insertar un registro, MySQL le asignará NULL automáticamente
  `departamento` varchar(100) DEFAULT NULL,     
  `region` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`municipio_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci; -- InnoDB permite: PK, FK entre otras cosas
															        --  DEFAULT CHARSET=utf8mb4: Caracteres que se van a manejar por defecto.

