-- CREACIÓN TABLA ALERTAS AMBIENTALES

CREATE TABLE if not exists `raw_alertas_ambientales` (
  `alerta_id` int NOT NULL,
  `nivel_alerta` varchar(50) DEFAULT NULL,
  `contaminante_causante` varchar(50) DEFAULT NULL,
  `descripcion` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`alerta_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `raw_alertas_ambientales` VALUES (0,'SIN ALERTA','NINGUNO','Medición en parámetros normales. Sin evento de alerta.'),(1,'AMARILLA','PM2.5','Excedencia moderada de los límites normativos permitidos en la zona'),(2,'Amarilla ','PM10','Excedencia moderada de material particulado PM10'),(3,'amarilla','O3','Concentración elevada de ozono troposférico'),(4,'NARANJA','PM2.5','Nivel nocivo de contaminación para grupos sensibles'),(5,'Naranja','NO2','Nivel alto de dióxido de nitrógeno por tráfico denso'),(6,'ROJA','PM2.5','Nivel de contaminación peligroso para la salud pública general'),(7,'Roja','PM10','Emergencia ambiental por material particulado grueso'),(8,'  ROJA ','SO2','Emergencia ambiental por emisiones industriales');

-- CREACIÓN TABLA CONTAMINANTES

CREATE TABLE if not exists `raw_contaminantes` (
  `contaminante_id` int NOT NULL,
  `nombre` varchar(100) DEFAULT NULL,
  `codigo` varchar(20) DEFAULT NULL,
  `unidad_medida` varchar(20) DEFAULT NULL,
  `categoria` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`contaminante_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `raw_contaminantes` VALUES (1,'Material Particulado PM2.5','PM25','µg/m3','Partículas'),(2,'Material Particulado PM2.5 ','PM2.5','ug/m3','partículas'),(3,'Material Particulado PM10','PM10','µg/m3','Partículas'),(4,'Dióxido de Nitrógeno','NO2','µg/m3','Gases'),(5,'Dioxido de Nitrogeno','no2','ug/m3','gases'),(6,'Ozono','O3','µg/m3','Gases'),(7,'Monóxido de Carbono','CO','mg/m3','Gases'),(8,'Dióxido de Azufre','SO2','µg/m3','Gases');

-- CREACIÓN TABLA ESTACIONES

CREATE TABLE if not exists `raw_estaciones` (
  `estacion_id` varchar(10) NOT NULL,
  `nombre_estacion` varchar(150) DEFAULT NULL,
  `municipio_id` varchar(10) DEFAULT NULL,
  `tipo_estacion` varchar(50) DEFAULT NULL,
  `latitud` decimal(10,6) DEFAULT NULL,
  `longitud` decimal(10,6) DEFAULT NULL,
  `fecha_instalacion` varchar(30) DEFAULT NULL,
  `estado` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`estacion_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

