  `fecha` varchar(20) DEFAULT NULL,
  `hora` int DEFAULT NULL,
  `concentracion` varchar(30) DEFAULT NULL,
  `temperatura` varchar(30) DEFAULT NULL,
  `humedad` varchar(30) DEFAULT NULL,
  `velocidad_viento` varchar(30) DEFAULT NULL,
  `calidad_dato` varchar(50) DEFAULT NULL
 ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

