SELECT TABLE_NAME, CONSTRAINT_NAME, CONSTRAINT_TYPE       -- Consulta el catálogo de MySQL y muéstrame el nombre de cada tabla, el nombre de sus restricciones y el tipo de restricción,
FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS                 -- pero solamente para las tablas de la base de datos ambiental_raw, y ordénalas por nombre de tabla
WHERE TABLE_SCHEMA = 'ambiental_raw'
ORDER BY TABLE_NAME;

-- Eliminé las claves foráneas en Bronze para que las relaciones entre las tablas no impidieran cargar los datos originales. 
